public class Time {
    public static void main(String[] args) {
        // a) Declare and initialize variables
        int hours = 15;
        int minutes = 10;
        int seconds = 30;

        // c) Calculate seconds since midnight
        int secondsSinceMidnight = hours * 3600 + minutes * 60 + seconds;
        System.out.println(secondsSinceMidnight + " seconds have passed since midnight.");

        // d) Calculate seconds left until midnight
        int secondsLeftUntilMidnight = (24 * 3600) - secondsSinceMidnight;
        System.out.println(secondsLeftUntilMidnight + " seconds are left until midnight.");

        // e) Declare and initialize variables for the current time
        int currentHours = 15;
        int currentMinutes = 17;
        int currentSeconds = 51;

        // Calculate elapsed time
        int elapsedTime = (currentHours * 3600 + currentMinutes * 60 + currentSeconds) - secondsSinceMidnight;
        System.out.println("Since I started with the task " + elapsedTime + " seconds have passed.");
    }
}
```

