        System.out.println(startSecondsSinceMidnight + " seconds have passed since midnight.");

        // d) Calculate seconds left until midnight
        int secondsInADay = 24 * 3600;
        int secondsLeftUntilMidnight = secondsInADay - startSecondsSinceMidnight;

