public class Time {
    public static void main(String[] args) {
        // a) Define variables with the given time values
        int startHours = 15;
        int startMinutes = 10;
        int startSeconds = 30;

        // c) Calculate total seconds since midnight
        int totalSecondsSinceMidnight = startHours * 3600 + startMinutes * 60 + startSeconds;
        System.out.println(totalSecondsSinceMidnight + " seconds have passed since midnight.");

        // d) Calculate seconds left until midnight
        int secondsInADay = 24 * 3600;
        int secondsLeftUntilMidnight = secondsInADay - totalSecondsSinceMidnight;
        System.out.println(secondsLeftUntilMidnight + " seconds are left until midnight.");

        // e) Define variables with the new time values
        int currentHours = 15;
        int currentMinutes = 17;
        int currentSeconds = 51;

        // Calculate total seconds since the start time
        int totalSecondsSinceStartTime = currentHours * 3600 + currentMinutes * 60 + currentSeconds;
        int timePassedSinceStart = totalSecondsSinceStartTime - totalSecondsSinceMidnight;
        System.out.println("Since I started with the task " + timePassedSinceStart + " seconds have passed.");
    }
}
